#define RV_DEL1_LEN 4701
#define RV_DAP2A 11056
#define RV_DAP2A_LEN 2636
#define RV_DAP2B 13693
#define RV_DAP2B_LEN 2292
#define RV_DEL2 15986
#define RV_DEL2_LEN 6590
#define RV_SMEAR_OFFSET 14
#define RV_SMEAR_DEPTH 83
#define RV_SMEAR_WRITE 138
#define RV_DEL2_OFFSET 6450
#define RV_DEL2_DEPTH 138
#endif

/* How far back a read goes (del2's tail), and the buffer: the ring, the
 * reads past its end, and the mirrored writes near its wrap. */
#define RV_MAX_REACH (RV_DEL2 + RV_DEL2_LEN)
#define RV_BUFFER_WORDS (RV_SIZE + RV_MAX_REACH + RV_DEL2 + 2)

/* The run kernel's parameter block (byte offsets). */
#define RVK_GAIN_AMOUNT 0
#define RVK_KAP 4
#define RVK_KRT_KLP 8
#define RVK_LP 12
#define RVK_SMEAR_OFF 16
#define RVK_SMEAR_W 20
#define RVK_D2_OFF 24
#define RVK_D2_W 28

#endif  /* OP1CLOUDS_CORE_REVERB_LAYOUT_H_ */
